sql.findbad:
SELECT * FROM {{RAW}}
WHERE balance IS NULL OR balance < 0
   OR state IS NULL OR state NOT IN ('VA','FL','NJ')
   OR status IS NULL OR status NOT IN ('Current','Delinquent','Paid')
ORDER BY loan_id;

sql.split:
CREATE OR REPLACE VIEW {{ACCEPTED}} AS
SELECT loan_id, balance, state, status FROM {{CHECKED}}
WHERE quality_result = 'PASS';

CREATE OR REPLACE VIEW {{EXCEPTIONS}} AS
SELECT * FROM {{CHECKED}} WHERE quality_result <> 'PASS';

SELECT 'accepted' AS result, COUNT(*) AS row_count FROM {{ACCEPTED}}
UNION ALL
SELECT 'exceptions', COUNT(*) FROM {{EXCEPTIONS}};

sql.comment:
COMMENT ON TABLE {{RAW}}
IS 'Synthetic learning data. One row per loan. Not a production data source.';

COMMENT ON COLUMN {{RAW}}.balance
IS 'Outstanding principal in USD for this exercise. Must be present and nonnegative.';

sql.snapshot:
CREATE OR REPLACE TABLE {{SNAPSHOT}}
USING DELTA AS
SELECT current_timestamp() AS captured_at, * FROM {{SCORE}};

